def metric(data: pd.DataFrame) -> float:
    t1_a = (1, 1, 0, 0, 0)
    t1_b = (0, 0, 1, 1, 1)

    t2_a = (1, 0, 0, 1, 0)
    t2_b = (0, 1, 1, 0, 0)

    t3_a = (1, 0, 0, 0, 0)
    t3_b = (0, 0, 1, 1, 0)

    t4_a = (0, 1, 1, 0, 0)
    t4_b = (0, 1, 0, 1, 1)

    t5_a = (1, 0, 1, 0, 0)
    t5_b = (0, 1, 0, 1, 1)

    a1, a2, a3, a4, a5 = 0, 0, 0, 0, 0

    for _, row in data.iterrows():
        a = tuple(row['option_a_ratings'])
        b = tuple(row['option_b_ratings'])
        resp = row['response']

        if a == t1_a and b == t1_b:
            if resp == 0: a1 += 1
        elif a == t1_b and b == t1_a:
            if resp == 1: a1 += 1

        elif a == t2_a and b == t2_b:
            if resp == 0: a2 += 1
        elif a == t2_b and b == t2_a:
            if resp == 1: a2 += 1

        elif a == t3_a and b == t3_b:
            if resp == 0: a3 += 1
        elif a == t3_b and b == t3_a:
            if resp == 1: a3 += 1

        elif a == t4_a and b == t4_b:
            if resp == 0: a4 += 1
        elif a == t4_b and b == t4_a:
            if resp == 1: a4 += 1

        elif a == t5_a and b == t5_b:
            if resp == 0: a5 += 1
        elif a == t5_b and b == t5_a:
            if resp == 1: a5 += 1

    return float(a1 + a2 - a3 - a4 - a5)

